{
  "hypotheses": [
    {
      "text": "CIK values are stored as integers in the source EDGAR tables but as strings in the ExplainWhy semantic layer, causing foreign‑key violations when the layer tries to join on cik.",
      "how_to_test": "SELECT cp.cik FROM edgar.company_profiles cp WHERE cp.cik NOT IN (SELECT company::int FROM lightning.metastore.explainwhy.explainwhy_usl.company);"
    },
    {
      "text": "Some companies report revenue facts with a fiscal_year or fiscal_period that does not match any valid period_frame allowed by the semantic layer’s domain (e.g., NULL or malformed period_frame), breaking the layer’s period_frame NOT NULL rule.",
      "how_to_test": "SELECT rf.cik, rf.fiscal_year, rf.fiscal_period, rf.period_frame FROM edgar.revenue_facts rf WHERE rf.period_frame IS NULL OR rf.period_frame NOT LIKE 'CY%' AND rf.period_frame IS NOT NULL;"
    },
    {
      "text": "Duplicate revenue facts for the same CIK, concept, and period appear in different filings (e.g., a 10‑Q followed by an amended 10‑Q/A) and the semantic layer’s uniqueness constraint on (cik, concept, period_start, period_end, form_type) is violated.",
      "how_to_test": "SELECT cik, concept, period_start, period_end, form_type, COUNT(*) AS dup_cnt FROM edgar.revenue_facts GROUP BY cik, concept, period_start, period_end, form_type HAVING COUNT(*) > 1;"
    },
    {
      "text": "Certain companies have undergone CIK changes due to mergers, acquisitions, or re‑registrations, leading to stale CIK entries in the company_profiles table that no longer match the current CIK used in revenue_facts, creating orphaned foreign‑key references.",
      "how_to_test": "SELECT cp.cik AS profile_cik, rf.cik AS fact_cik FROM edgar.company_profiles cp LEFT JOIN edgar.revenue_facts rf ON cp.cik = rf.cik WHERE rf.cik IS NULL GROUP BY cp.cik, rf.cik HAVING COUNT(rf.accession_number) = 0;"
    }
  ]
}
